import{_ as o,c as t,o as a,ag as i}from"./chunks/framework.DZ_cNctr.js";const r="/docs/screenshots/vsi-slide.webp",f=JSON.parse('{"title":"Olympus VSI Viewer","description":"Free online Olympus VSI viewer: open .vsi files from cellSens, VS120 and VS200 slide scanners in your browser, with Label and Macro pictures, fluorescence channels, Z-stacks and time series. From a folder or a zip. Nothing to install.","frontmatter":{"title":"Olympus VSI Viewer","description":"Free online Olympus VSI viewer: open .vsi files from cellSens, VS120 and VS200 slide scanners in your browser, with Label and Macro pictures, fluorescence channels, Z-stacks and time series. From a folder or a zip. Nothing to install."},"headers":[],"relativePath":"guides/olympus-vsi.md","filePath":"guides/olympus-vsi.md"}'),s={name:"guides/olympus-vsi.md"};function n(l,e,d,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="olympus-vsi-viewer" tabindex="-1">Olympus VSI Viewer <a class="header-anchor" href="#olympus-vsi-viewer" aria-label="Permalink to &quot;Olympus VSI Viewer&quot;">​</a></h1><p>Open the images Olympus and Evident cellSens save as <code>.vsi</code>: brightfield slides from a VS120 or VS200 scanner, and fluorescence, 16-bit, Z-stack and time series images. No cellSens, no Bio-Formats export, no upload. The viewer reads only the part you look at, so a large slide opens without a conversion step.</p><p><img src="'+r+'" alt="Image_00.vsi open in the viewer: an H&amp;E slide from a VS200 scanner, with its Label and Macro pictures"></p><p>A VSI image is a <code>.vsi</code> file plus a folder next to it, named like the file with an underscore on each side: <code>Image_00.vsi</code> and <code>_Image_00_</code>. The pictures are in the folder. Keep both together.</p><h2 id="how-to-open-a-vsi-file" tabindex="-1">How to Open a VSI File <a class="header-anchor" href="#how-to-open-a-vsi-file" aria-label="Permalink to &quot;How to Open a VSI File&quot;">​</a></h2><ul><li><strong>A folder on your disk</strong>, in Chrome and Edge. Drop the folder that holds the <code>.vsi</code> file and its <code>_name_</code> folder on the viewer. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>One zip made without compression</strong>, in any browser, from your disk or its address. See <a href="./local-files.html#zip-without-compression">Zip Without Compression</a>.</li><li><strong>An address</strong> of that zip: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>A <code>.vsi</code> file dropped on its own, or opened by its own link, cannot open, because the pictures are in the folder. The viewer says so and tells you what to do.</p><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Brightfield slides</strong> (H&amp;E and other stains) open as slides: zoom from the whole slide down to single cells. Tiles the scanner did not store show the slide&#39;s background colour.</li><li><strong>Label and Macro.</strong> They appear under the title. Click one to enlarge it. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Fluorescence, 16-bit data, Z-stacks and time series</strong> open as microscopy images, with every channel by the name the file gives it. Sliders step through Z and time. A Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>Several images in one file</strong>, such as a scan at 20x and another at 40x. Each scan is in the <strong>Series</strong> list. On a slide, the Label and Macro show as pictures under the title.</li><li><strong>Compression.</strong> JPEG, JPEG 2000, lossless JPEG and uncompressed data.</li><li><strong>Pixel size</strong> from the file, so measurements read in µm. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>The viewer was checked against Bio-Formats on sample files from the VS120 and VS200 scanners and from the cellSens software: the regions it opened matched. JPEG 2000 pictures stay within one grey level of other decoders.</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What you opened</th><th>What the viewer says</th></tr></thead><tbody><tr><td>A <code>.vsi</code> file without its folder</td><td>A VSI image is a .vsi file and the folder <code>_name_</code> beside it. Drop the folder that holds both, or a zip of them made without compression (zip -0 -r image.zip folder).</td></tr><tr><td>A <code>.vsi</code> file whose folder holds no image files, after an interrupted copy</td><td>The folder <code>_name_</code> holds no image files. Copy it again from where the image was saved, then open the folder that holds both.</td></tr><tr><td>The link of a <code>.vsi</code> file</td><td>A VSI image opens from a link only as a zip of the .vsi file and its <code>_name_</code> folder, made without compression (zip -0 -r image.zip folder).</td></tr><tr><td>A zip made with compression</td><td>The files in this zip are compressed, so they cannot be read in parts. Unzip it and open the folder, or make the zip again without compression (zip -0 -r slide.zip folder).</td></tr><tr><td>A file with nothing the viewer can show</td><td>This file holds no image the viewer can show, followed by the reasons.</td></tr></tbody></table><p>When one image of a file is left out and the others open, a notice reads &quot;Not shown: image (reason)&quot;. For example: an extended focus image, 32-bit or other pixel types the viewer does not read yet, PNG, BMP or 16-bit JPEG tiles, spectral and phase series, a data file that is missing or damaged, or a colour image with several channels.</p><p>Confocal images from an Olympus or Evident FluoView FV3000 or FV4000 are saved as <code>.oir</code> instead. See the <a href="./olympus-oir.html">Olympus OIR Viewer</a>.</p><h2 id="public-vsi-files-to-try" tabindex="-1">Public VSI Files to Try <a class="header-anchor" href="#public-vsi-files-to-try" aria-label="Permalink to &quot;Public VSI Files to Try&quot;">​</a></h2><p>Download an image with its folder, then drop the folder on the viewer. Or <a href="./local-files.html#zip-without-compression">make a zip without compression</a>.</p><ul><li><strong>Image_00</strong>: H&amp;E mouse liver, VS200. <a href="https://zenodo.org/records/12072433" target="_blank" rel="noreferrer">Zenodo 12072433</a>, CC BY 4.0.</li><li><strong>8jky</strong>: H&amp;E cat intestine, VS120. <a href="https://www.ebi.ac.uk/biostudies/bioimages/studies/S-BIAD1129" target="_blank" rel="noreferrer">BioImage Archive S-BIAD1129</a>, CC BY 4.0.</li><li><strong>OS-2</strong>: Ki-67 immunohistochemistry, VS120, JPEG 2000. <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Olympus/" target="_blank" rel="noreferrer">OpenSlide test data</a>, free to use and distribute, with or without modification.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a zip by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>Sample files named above are credited to their records. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;Olympus VSI file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',25)])])}const u=o(s,[["render",n]]);export{f as __pageData,u as default};
